CREATE CATALOG IF NOT EXISTS retail_prod COMMENT 'Orders, customers and payments for a retail business, modelled as bronze, silver and gold.';
CREATE SCHEMA IF NOT EXISTS retail_prod.landing COMMENT 'Landing zone: source files as delivered';
CREATE SCHEMA IF NOT EXISTS retail_prod.bronze COMMENT 'Raw, append-only copies of source data as text';
CREATE SCHEMA IF NOT EXISTS retail_prod.silver COMMENT 'Typed, validated, deduplicated current state';
CREATE SCHEMA IF NOT EXISTS retail_prod.gold COMMENT 'Curated aggregates for consumption';
CREATE SCHEMA IF NOT EXISTS retail_prod.governance COMMENT 'Mask functions and other governance objects';
CREATE VOLUME IF NOT EXISTS retail_prod.landing.raw COMMENT 'Landing files by source: one folder per source table';

-- Column masks. Bind them in the pipeline SQL; they must exist first.
CREATE OR REPLACE FUNCTION retail_prod.governance.mask_email(v STRING)
RETURNS STRING
COMMENT 'Column mask (email): readers in the privileged and runner groups see the real value'
RETURN CASE
  WHEN v IS NULL THEN NULL
  WHEN is_account_group_member('lakehouse_pii_readers') OR is_account_group_member('lakehouse_pipeline_runners') THEN v
  ELSE concat('***@', substring_index(v, '@', -1))
END;

CREATE OR REPLACE FUNCTION retail_prod.governance.mask_redact(v STRING)
RETURNS STRING
COMMENT 'Column mask (redact): readers in the privileged and runner groups see the real value'
RETURN CASE
  WHEN v IS NULL THEN NULL
  WHEN is_account_group_member('lakehouse_pii_readers') OR is_account_group_member('lakehouse_pipeline_runners') THEN v
  ELSE '[REDACTED]'
END;

